const op = msg.payload;
const size = bytes => {
    const units = ["B", "KB", "MB", "GB", "TB"];
    let i = 0;
    while (bytes >= 1024 && i < units.length - 1) { bytes /= 1024; i++; }
    return `${bytes.toFixed(i ? 1 : 0)} ${units[i]}`;
};
const escape = text => String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const what = { backup: "Backup", check: "Repository check", prune: "Prune" }[msg.operationType];
const result = msg.status === "STATUS_WARNING" ? "finished with warnings" : "failed";
// Repository tasks such as check and prune have no plan
const plan = op.planId && op.planId !== "_system_" ? op.planId : null;

const rows = [];
if (plan) rows.push(["Plan", plan]);
rows.push(["Repository", op.repoId]);
if (op.snapshotId) {
    rows.push(["Snapshot", op.snapshotId.slice(0, 8)]);
    const s = op.operationBackup && op.operationBackup.lastStatus && op.operationBackup.lastStatus.summary;
    if (s) {
        const n = value => Number(value || 0);
        rows.push(
            ["Files", `${n(s.filesNew)} new, ${n(s.filesChanged)} changed, ${n(s.filesUnmodified)} unmodified`],
            ["Data added", `${size(n(s.dataAdded))} (${size(n(s.totalBytesProcessed))} processed)`],
            ["Duration", `${Math.round(n(s.totalDuration))}s`]
        );
    }
}
const error = (op.displayMessage || "").trim();

// The subject, an HTML body and a plain text body for mail apps that don't show HTML
msg.topic = `Backrest: ${what} of ${plan || op.repoId} ${result}`;
msg.payload =
    '<div style="font-family:sans-serif">\n' +
    `<p><strong>${what} ${result}</strong></p>\n` +
    "<table>\n" +
    rows.map(([name, value]) => `<tr><td style="padding-right:16px;color:#666">${name}</td><td>${escape(value)}</td></tr>\n`).join("") +
    "</table>\n" +
    (error ? `<pre style="white-space:pre-wrap">${escape(error)}</pre>\n` : "") +
    "</div>";
msg.plaintext = [`${what} ${result}`, "", ...rows.map(([name, value]) => `${name}: ${value}`)]
    .concat(error ? ["", error] : [])
    .join("\n");
return msg;
